            var seen=new System.Collections.Generic.HashSet<string>();foreach(var s in active){var rt=(RectTransform)s.transform;var key=rt.anchorMin+"/"+rt.anchorMax+"/"+rt.offsetMin+"/"+rt.offsetMax;if(!seen.Add(key))s.Graphic.enabled=false;}
        }}
