    public static string Forecast(){Load();SliceForecast();const string partPath=Root+"Parts/UIForecastRaceCard.prefab";if(AssetDatabase.LoadAssetAtPath<GameObject>(partPath)==null){var part=new GameObject("UIForecastRaceCard",typeof(RectTransform),typeof(LayoutElement));try{PrefabUtility.SaveAsPrefabAsset(part,partPath);}finally{UnityEngine.Object.DestroyImmediate(part);}}
