    static void SliceForecast(){const string path="Assets/Art/UI/Sprites/Common/LuigiForecastPortraits.png";AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var ti=(TextureImporter)AssetImporter.GetAtPath(path);ti.textureType=TextureImporterType.Sprite;ti.spriteImportMode=SpriteImportMode.Multiple;ti.alphaIsTransparency=true;ti.mipmapEnabled=false;ti.npotScale=TextureImporterNPOTScale.None;ti.maxTextureSize=2048;ti.textureCompression=TextureImporterCompression.CompressedHQ;ti.SaveAndReimport();var f=new SpriteDataProviderFactories();f.Init();var dp=f.GetSpriteEditorDataProviderFromObject(ti);if(dp==null)throw new Exception("No sprite provider");dp.InitSpriteEditorDataProvider();var cap=dp.GetDataProvider<ISpriteFrameEditCapability>();if(cap==null)throw new Exception("No sprite capability");foreach(var c in new[]{EEditCapability.CreateAndDeleteSprite,EEditCapability.EditSpriteName,EEditCapability.EditSpriteRect,EEditCapability.EditPivot,EEditCapability.EditBorder})if(!cap.GetEditCapability().HasCapability(c))throw new Exception("Unsupported "+c);var old=dp.GetSpriteRects();var tex=new Texture2D(2,2);try{tex.LoadImage(System.IO.File.ReadAllBytes(path));var pixels=tex.GetPixels32();var output=new SpriteRect[6];for(int i=0;i<6;i++){int left=i%3*512,top=i/3*512,x0=1536,y0=1024,x1=-1,y1=-1;for(int y=top;y<top+512;y++)for(int x=left;x<left+512;x++)if(pixels[(1023-y)*1536+x].a>48){x0=Math.Min(x0,x);y0=Math.Min(y0,y);x1=Math.Max(x1,x);y1=Math.Max(y1,y);}if(x1<0)throw new Exception("Empty forecast cell "+i);var name="Forecast"+i;output[i]=new SpriteRect{name=name,spriteID=old.FirstOrDefault(r=>r.name==name)?.spriteID??GUID.Generate(),rect=new Rect(x0,1023-y1,x1-x0+1,y1-y0+1),pivot=C,alignment=SpriteAlignment.Center};}dp.SetSpriteRects(output);var ids=dp.GetDataProvider<ISpriteNameFileIdDataProvider>();if(ids==null)throw new Exception("No stable sprite IDs");ids.SetNameFileIdPairs(output.Select(r=>new SpriteNameFileIdPair(r.name,r.spriteID)));dp.Apply();ti.SaveAndReimport();}finally{UnityEngine.Object.DestroyImmediate(tex);}}

